 var x=v[0]*t/3*sign,y=v[1]*t/3*sign,k=1;
 if(x>0)k=Math.min(k,(.99-p[0])/x);if(x<0)k=Math.min(k,(.01-p[0])/x);
 if(y>0)k=Math.min(k,(.99-p[1])/y);if(y<0)k=Math.min(k,(.01-p[1])/y);
