function currentFlyScale(){return (bankIndex===0&&selected>=1&&selected<=flyScalePerM.length)?flyScalePerM[selected-1]:0;}
var bankIndex=0,flightCount=700,dataFolder="../data/",filePrefix="fruchtfliege_",flightTimes=bankTimes[0];
var closureTimes={},durationKey='',selectionDuration=0;
function readFlightSamples(n){var name='000'+n;return readJSON(base()+dataFolder+filePrefix+'flug_'+name.slice(-3)+'.json').samples;}
function totalDuration(){
 var b=bounds(),key=b[0]+':'+b[1]+':'+looping;
 if(key===durationKey)return selectionDuration;
 var total=0;
 for(var n=b[0];n<=b[1];n++){
  total+=flightTimes.duration[n-1];
  if(n<b[1])total+=flightTimes.next[n-1];
 }
 if(looping){
  if(b[0]===b[1])total+=flightTimes.self[b[0]-1];
  else if(b[0]===1&&b[1]===flightCount)total+=flightTimes.next[flightCount-1];
  else{
   var pair=b[1]+':'+b[0];
   if(typeof closureTimes[pair]==='undefined')closureTimes[pair]=makeBridge(readFlightSamples(b[1]),readFlightSamples(b[0])).duration;
   total+=closureTimes[pair];
  }
 }
 selectionDuration=total/1000;durationKey=key;return selectionDuration;
}
function species(v){
 v=Number(v);if(!isFinite(v))return;v=v?1:0;
 if(v===bankIndex){sync();return;}
 task.cancel();running=false;bridge=null;
 bankIndex=v;flightCount=v?42:700;dataFolder='../data/';filePrefix=v?'moskito_':'fruchtfliege_';flightTimes=bankTimes[v];
 closureTimes={};durationKey='';selectionDuration=0;
 selected=1;first=1;finalFlight=Math.min(10,flightCount);
 choose(1);
}
function sync(){outlet(1,'limits','maximum',flightCount);outlet(1,'species','set',bankIndex);outlet(1,'flightlabel','set','Flug 1–'+flightCount);outlet(1,'flight','set',selected);outlet(1,'speed','set',rate);outlet(1,'duration','set',totalDuration());outlet(1,'mode','set',playmode);outlet(1,'loop','set',looping);outlet(1,'first','set',first);outlet(1,'last','set',finalFlight);}
function status(s){outlet(2,s);}
function init(){if(ready)return;ready=true;choose(1);}
function loadbang(){init();}
function number(v){v=Number(v);return isFinite(v)?Math.max(1,Math.min(flightCount,Math.floor(v))):null;}
function loadFlight(n){
 bridge=null;
 try{var name='000'+n;var data=readJSON(base()+dataFolder+filePrefix+'flug_'+name.slice(-3)+'.json');if(!data.samples||data.samples.length<2)throw new Error('Keine Flugpunkte');samples=data.samples;selected=n;elapsed=0;index=0;sync();return true;}catch(e){samples=[];running=false;task.cancel();status('Dateifehler');error('Flugbahn: '+String(e)+'\n');return false;}}
function choose(n){task.cancel();running=false;if(loadFlight(n)){emit();status('Bereit');}}
// Explicit flight selection means single-flight playback; range/all advance internally.
function flight(n){n=number(n);if(n===null)return;playmode=0;choose(n);}
function mode(v){v=Number(v);if(!isFinite(v))return;playmode=Math.max(0,Math.min(2,Math.floor(v)));choose(bounds()[0]);}
function firstflight(v){v=number(v);if(v===null)return;first=v;if(finalFlight<first)finalFlight=first;if(playmode===1)choose(first);else sync();}
function lastflight(v){v=number(v);if(v===null)return;finalFlight=v;if(first>finalFlight)first=finalFlight;if(playmode===1)choose(first);else sync();}
function loop(v){advance(Date.now());looping=Number(v)?1:0;sync();}
function emitMeta(isMeasured,sourceMs){
 // Outlet 4: species, flight, measured, scale_per_m, source_time_ms.
 // Only measured fruit-fly data are enabled for biological manoeuvre analysis.
 var active=(bankIndex===0&&isMeasured)?1:0;
 outlet(3,[bankIndex,selected,active,active?currentFlyScale():0,sourceMs]);
}
function emit(){
 if(bridge){
  // Synthetic connection: keep XY playback, but explicitly disable manoeuvre analysis.
  emitMeta(0,bridge.elapsed);
  outlet(0,at(bridge.samples,bridge.elapsed));
  outlet(1,'time','set',bridge.elapsed/1000);
  return;
 }
 if(!samples.length)return;
 while(index<samples.length-2&&samples[index+1][0]<=elapsed)index++;
 var a=samples[index],b=samples[index+1],u=Math.max(0,Math.min(1,(elapsed-a[0])/(b[0]-a[0])));
 // Metadata must arrive before XY so downstream analysis has the correct scale/time.
 emitMeta(1,elapsed);
 outlet(0,[a[1]+u*(b[1]-a[1]),a[2]+u*(b[2]-a[2])]);
 outlet(1,'time','set',elapsed/1000);
}
function advance(now){
 if(!running)return;
 var remaining=Math.max(0,now-last)*rate;last=now;
 while(running){
  if(bridge){
   var leftBridge=bridge.duration-bridge.elapsed;
   if(remaining<leftBridge){bridge.elapsed+=remaining;return;}
   remaining-=leftBridge;bridge=null;elapsed=0;index=0;sync();status('Laeuft');
   if(remaining===0)return;
  }
  var duration=samples[samples.length-1][0],left=duration-elapsed;
  if(remaining<left){elapsed+=remaining;return;}
  remaining-=left;elapsed=duration;
  var b=bounds(),next=selected<b[1]?selected+1:(looping?b[0]:0);
  if(!next){running=false;task.cancel();status('Ende');return;}
  var previous=samples;
  if(!loadFlight(next))return;
  bridge=makeBridge(previous,samples);status('Verbindung');
  if(remaining===0)return;
 }
}
function start(){if(!ready)init();if(!samples.length||running)return;if(elapsed>=samples[samples.length-1][0]){if(!loadFlight(bounds()[0]))return;}running=true;last=Date.now();emit();status(bridge?'Verbindung':'Laeuft');task.schedule(10);}
function stop(){advance(Date.now());running=false;task.cancel();emit();status('Gestoppt');}
function restart(){var was=running;if(!loadFlight(bounds()[0]))return;running=was;last=Date.now();emit();status(running?'Laeuft':'Bereit');}
function speed(v){v=Number(v);if(!isFinite(v))return;advance(Date.now());rate=Math.max(0,Math.min(100,v));sync();emit();}
function msg_int(v){if(v)start();else stop();}
function tick(){if(!running)return;advance(Date.now());emit();if(running)task.schedule(10);}
function notifydeleted(){task.cancel();task.freepeer();}
